-- Hayola Tasks. Apply once to a NEW Supabase project. No seed data.
begin;
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text not null check(length(btrim(full_name)) between 1 and 120),email text not null unique,job_title text not null default '',team text not null default 'Product' check(team in ('Product','Design','Engineering','Marketing','Other')),timezone text not null default 'Asia/Tehran',weekly_capacity numeric not null default 40 check(weekly_capacity between 1 and 168),last_seen_at timestamptz,created_at timestamptz not null default now());
create table public.projects(id uuid primary key default gen_random_uuid(),owner_id uuid not null references public.profiles(id),name text not null check(length(btrim(name)) between 1 and 160),description text not null default '' check(length(description)<=5000),status text not null default 'Planning' check(status in ('Planning','In progress','In review','Shipped')),color text not null default 'blue' check(color in ('blue','purple','pink','orange','green','teal','indigo','yellow')),icon text not null default 'folder',start_date date not null default current_date,due_date date,created_at timestamptz not null default now(),deleted_at timestamptz,check(due_date is null or due_date>=start_date));
create table public.project_members(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.projects(id) on delete cascade,user_id uuid not null references public.profiles(id),role text not null default 'member' check(role in ('owner','member')),status text not null default 'invited' check(status in ('invited','accepted','declined','removed')),invited_by uuid not null references public.profiles(id),created_at timestamptz not null default now(),unique(project_id,user_id));
create index members_by_user on public.project_members(user_id,status);
create table public.project_pins(user_id uuid not null references public.profiles(id) on delete cascade,project_id uuid not null references public.projects(id) on delete cascade,primary key(user_id,project_id));
create table public.tasks(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.projects(id),created_by uuid not null references public.profiles(id),title text not null check(length(btrim(title)) between 1 and 300),status text not null default 'To do' check(status in ('To do','In progress','In review','Done')),priority text not null default 'Medium' check(priority in ('Low','Medium','High','Urgent')),assignee_id uuid references public.profiles(id),due_date date,estimate_hours numeric not null default 2 check(estimate_hours between 0 and 9999),sort_order double precision not null default 0,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),started_at timestamptz,completed_at timestamptz,deleted_at timestamptz,revision integer not null default 1);
create index tasks_by_project on public.tasks(project_id,status,sort_order);
create index tasks_by_assignee on public.tasks(assignee_id,due_date) where deleted_at is null;
create table public.task_status_events(id uuid primary key default gen_random_uuid(),task_id uuid not null references public.tasks(id) on delete cascade,project_id uuid not null references public.projects(id),actor_id uuid references public.profiles(id),from_status text,to_status text not null,created_at timestamptz not null default now());
create table public.subtasks(id uuid primary key default gen_random_uuid(),task_id uuid not null references public.tasks(id) on delete cascade,title text not null check(length(btrim(title)) between 1 and 300),done boolean not null default false,created_at timestamptz not null default now());
create table public.comments(id uuid primary key default gen_random_uuid(),task_id uuid not null references public.tasks(id) on delete cascade,author_id uuid not null references public.profiles(id),body text not null check(length(btrim(body)) between 1 and 10000),created_at timestamptz not null default now());
create table public.milestones(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.projects(id) on delete cascade,title text not null check(length(btrim(title)) between 1 and 300),due_date date not null,done boolean not null default false,created_at timestamptz not null default now());
create table public.calendar_events(id uuid primary key default gen_random_uuid(),project_id uuid references public.projects(id),created_by uuid not null references public.profiles(id),title text not null check(length(btrim(title)) between 1 and 300),type text not null default 'Meeting' check(type in ('Meeting','Focus block','Review','Deadline','Team')),starts_at timestamptz not null,ends_at timestamptz not null,location text not null default '',meeting_url text not null default '',attendee_ids uuid[] not null default '{}',created_at timestamptz not null default now(),check(ends_at>starts_at and ends_at<=starts_at+interval '24 hours'),check(meeting_url='' or meeting_url ~ '^https://'));
create index calendar_by_start on public.calendar_events(starts_at);
create table public.focus_sessions(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id),task_id uuid references public.tasks(id),project_id uuid references public.projects(id),planned_seconds integer not null check(planned_seconds between 60 and 43200),elapsed_seconds integer not null default 0 check(elapsed_seconds>=0),status text not null default 'running' check(status in ('running','paused','completed','ended')),started_at timestamptz not null default now(),resumed_at timestamptz,ended_at timestamptz);
create unique index focus_one_active on public.focus_sessions(user_id) where status in ('running','paused');
create table public.user_settings(user_id uuid primary key references public.profiles(id) on delete cascade,theme text not null default 'dark' check(theme in ('dark','light','auto')),accent text not null default 'blue' check(accent in ('blue','purple','pink','orange','green','graphite')),wallpaper text not null default 'ash' check(wallpaper in ('ash','sand','sage','aurora','smoke','tide','bloom','ember','grove','dusk')),glass text not null default 'tinted' check(glass in ('clear','tinted')),reduce_transparency boolean not null default false,focus_minutes integer not null default 25 check(focus_minutes between 5 and 180),break_minutes integer not null default 5 check(break_minutes between 5 and 60),notifications jsonb not null default '{"mentions":true,"due_dates":true,"meetings":true,"digest":false,"focus_finished":true}'::jsonb check(jsonb_typeof(notifications)='object'));
create table public.notifications(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id),actor_id uuid references public.profiles(id),project_id uuid references public.projects(id),task_id uuid references public.tasks(id),kind text not null,body text not null,read_at timestamptz,created_at timestamptz not null default now(),dedupe_key text,unique(user_id,dedupe_key));
create index notifications_by_recipient on public.notifications(user_id,created_at desc);
create table public.activity_log(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.projects(id),actor_id uuid references public.profiles(id),task_id uuid references public.tasks(id),kind text not null,body text not null,created_at timestamptz not null default now());
create table public.direct_messages(id uuid primary key default gen_random_uuid(),sender_id uuid not null references public.profiles(id),recipient_id uuid not null references public.profiles(id),body text not null check(length(btrim(body)) between 1 and 10000),read_at timestamptz,created_at timestamptz not null default now(),check(sender_id<>recipient_id));

create function public.project_access(pid uuid) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.projects p where p.id=pid and p.deleted_at is null and (p.owner_id=(select auth.uid()) or exists(select 1 from public.project_members m where m.project_id=p.id and m.user_id=(select auth.uid()) and m.status='accepted'))) $$;
create function public.project_owner(pid uuid) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.projects where id=pid and owner_id=(select auth.uid())) $$;
create function public.shared_project(other uuid) returns boolean language sql stable security definer set search_path='' as $$ select other=(select auth.uid()) or exists(select 1 from public.project_members a join public.project_members b on a.project_id=b.project_id join public.projects p on p.id=a.project_id where a.user_id=(select auth.uid()) and b.user_id=other and a.status='accepted' and b.status='accepted' and p.deleted_at is null) $$;
create function public.task_access(tid uuid) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.tasks where id=tid and public.project_access(project_id)) $$;
create function public.create_profile() returns trigger language plpgsql security definer set search_path='' as $$ begin insert into public.profiles(id,full_name,email) values(new.id,coalesce(nullif(btrim(left(new.raw_user_meta_data->>'full_name',120)),''),'Team member'),lower(new.email));insert into public.user_settings(user_id) values(new.id);return new;end $$;
create trigger on_auth_user_created after insert on auth.users for each row execute function public.create_profile();
create function public.sync_profile_email() returns trigger language plpgsql security definer set search_path='' as $$ begin update public.profiles set email=lower(new.email) where id=new.id;return new;end $$;
create trigger on_auth_email_changed after update of email on auth.users for each row execute function public.sync_profile_email();
create function public.guard_profile() returns trigger language plpgsql set search_path='' as $$ begin if not exists(select 1 from pg_catalog.pg_timezone_names where name=new.timezone) then raise exception 'Invalid timezone';end if;return new;end $$;
create trigger profile_guard before insert or update on public.profiles for each row execute function public.guard_profile();
create function public.add_project_owner() returns trigger language plpgsql security definer set search_path='' as $$ begin insert into public.project_members(project_id,user_id,role,status,invited_by) values(new.id,new.owner_id,'owner','accepted',new.owner_id);insert into public.activity_log(project_id,actor_id,kind,body) values(new.id,new.owner_id,'project_created','created the project');return new;end $$;
create trigger project_created after insert on public.projects for each row execute function public.add_project_owner();
create function public.guard_task() returns trigger language plpgsql set search_path='' as $$ begin
 if TG_OP='UPDATE' and (new.project_id<>old.project_id or new.created_by<>old.created_by or new.created_at<>old.created_at) then raise exception 'Task identity cannot change';end if;
 if new.assignee_id is not null and not exists(select 1 from public.project_members where project_id=new.project_id and user_id=new.assignee_id and status='accepted') then raise exception 'Assignee must be an accepted project member';end if;
 new.updated_at=now();if TG_OP='INSERT' then new.created_at=now();new.revision=1;new.started_at=null;new.completed_at=null;else new.revision=old.revision+1;new.started_at=old.started_at;new.completed_at=old.completed_at;end if;
 if new.status='In progress' and new.started_at is null then new.started_at=now();end if;
 if new.status='Done' and (TG_OP='INSERT' or old.status<>'Done') then new.completed_at=now();elsif new.status<>'Done' then new.completed_at=null;end if;return new;end $$;
create trigger task_guard before insert or update on public.tasks for each row execute function public.guard_task();
create function public.log_task() returns trigger language plpgsql security definer set search_path='' as $$ begin
 if TG_OP='INSERT' or new.status<>old.status then insert into public.task_status_events(task_id,project_id,actor_id,from_status,to_status) values(new.id,new.project_id,auth.uid(),case when TG_OP='INSERT' then null else old.status end,new.status);insert into public.activity_log(project_id,actor_id,task_id,kind,body) values(new.project_id,auth.uid(),new.id,'task_status',case when TG_OP='INSERT' then 'created “'||new.title||'”' else 'moved “'||new.title||'” to '||new.status end);end if;
 if new.assignee_id is not null and new.assignee_id<>auth.uid() and (TG_OP='INSERT' or new.assignee_id is distinct from old.assignee_id) then insert into public.notifications(user_id,actor_id,project_id,task_id,kind,body) values(new.assignee_id,auth.uid(),new.project_id,new.id,'assignment','You were assigned “'||new.title||'”');end if;return new;end $$;
create trigger task_logged after insert or update on public.tasks for each row execute function public.log_task();
create function public.log_comment() returns trigger language plpgsql security definer set search_path='' as $$ declare t public.tasks;p record;begin select * into t from public.tasks where id=new.task_id;insert into public.activity_log(project_id,actor_id,task_id,kind,body) values(t.project_id,new.author_id,t.id,'comment','commented on “'||t.title||'”');for p in select u.id,u.full_name,s.notifications from public.profiles u join public.project_members m on m.user_id=u.id join public.user_settings s on s.user_id=u.id where m.project_id=t.project_id and m.status='accepted' and u.id<>new.author_id loop
 if strpos(lower(new.body),lower('@'||p.full_name))>0 and coalesce((p.notifications->>'mentions')::boolean,true) then insert into public.notifications(user_id,actor_id,project_id,task_id,kind,body) values(p.id,new.author_id,t.project_id,t.id,'mention','You were mentioned on “'||t.title||'”');elsif p.id=t.assignee_id then insert into public.notifications(user_id,actor_id,project_id,task_id,kind,body) values(p.id,new.author_id,t.project_id,t.id,'comment','New comment on “'||t.title||'”');end if;end loop;return new;end $$;
create trigger comment_logged after insert on public.comments for each row execute function public.log_comment();
create function public.guard_event() returns trigger language plpgsql set search_path='' as $$ begin
 if TG_OP='UPDATE' and (new.project_id is distinct from old.project_id or new.created_by<>old.created_by) then raise exception 'Event identity cannot change';end if;
 if new.project_id is null then if exists(select 1 from unnest(new.attendee_ids) a where a<>new.created_by) then raise exception 'Private events can only include their owner';end if;
 elsif exists(select 1 from unnest(new.attendee_ids) a where not exists(select 1 from public.project_members m where m.project_id=new.project_id and m.user_id=a and m.status='accepted')) then raise exception 'Attendees must be project members';end if;return new;end $$;
create trigger event_guard before insert or update on public.calendar_events for each row execute function public.guard_event();

create function public.find_registered_member(p_project_id uuid,p_email text) returns table(id uuid,full_name text,email text) language plpgsql security definer set search_path='' as $$ begin if not public.project_owner(p_project_id) or not public.project_access(p_project_id) then raise exception 'Only the project owner can find members';end if;return query select p.id,p.full_name,p.email from public.profiles p where lower(p.email)=lower(btrim(p_email)) limit 1;end $$;
create function public.add_project_member(p_project_id uuid,p_user_id uuid,p_direct boolean default false) returns void language plpgsql security definer set search_path='' as $$ declare pname text;begin
 if not public.project_owner(p_project_id) or not public.project_access(p_project_id) then raise exception 'Only the project owner can add members';end if;
 if exists(select 1 from public.project_members where project_id=p_project_id and user_id=p_user_id and status='accepted') then raise exception 'This person is already a member';end if;
 insert into public.project_members(project_id,user_id,status,invited_by) values(p_project_id,p_user_id,case when p_direct then 'accepted' else 'invited' end,auth.uid()) on conflict(project_id,user_id) do update set status=excluded.status,role='member',invited_by=auth.uid(),created_at=now();select name into pname from public.projects where id=p_project_id;
 insert into public.notifications(user_id,actor_id,project_id,kind,body) values(p_user_id,auth.uid(),p_project_id,case when p_direct then 'member_added' else 'invitation' end,case when p_direct then 'You were added to “'||pname||'”' else 'You were invited to “'||pname||'”' end);end $$;
create function public.pending_invitations() returns table(id uuid,project_id uuid,project_name text,inviter_name text,created_at timestamptz) language sql stable security definer set search_path='' as $$ select m.id,m.project_id,p.name,u.full_name,m.created_at from public.project_members m join public.projects p on p.id=m.project_id join public.profiles u on u.id=m.invited_by where m.user_id=auth.uid() and m.status='invited' and p.deleted_at is null order by m.created_at desc $$;
create function public.respond_invitation(p_id uuid,p_accept boolean) returns void language plpgsql security definer set search_path='' as $$ begin update public.project_members m set status=case when p_accept then 'accepted' else 'declined' end where m.id=p_id and m.user_id=auth.uid() and m.status='invited' and exists(select 1 from public.projects p where p.id=m.project_id and p.deleted_at is null);if not found then raise exception 'Invitation is no longer available';end if;end $$;
create function public.remove_project_member(p_project_id uuid,p_user_id uuid) returns void language plpgsql security definer set search_path='' as $$ begin if not public.project_owner(p_project_id) then raise exception 'Only the owner can remove members';end if;if exists(select 1 from public.projects where id=p_project_id and owner_id=p_user_id) then raise exception 'Owner cannot be removed';end if;update public.tasks set assignee_id=null where project_id=p_project_id and assignee_id=p_user_id;update public.project_members set status='removed' where project_id=p_project_id and user_id=p_user_id;end $$;

create function public.focus_command(p_action text,p_task_id uuid default null,p_minutes integer default 25) returns public.focus_sessions language plpgsql security definer set search_path='' as $$ declare s public.focus_sessions;pid uuid;delta integer;begin
 if auth.uid() is null then raise exception 'Sign in first';end if;perform pg_advisory_xact_lock(hashtext(auth.uid()::text));select * into s from public.focus_sessions where user_id=auth.uid() and status in ('running','paused') for update;
 if p_action='start' then if s.id is not null then raise exception 'A focus session is already active';end if;if p_minutes<5 or p_minutes>180 then raise exception 'Invalid session length';end if;if p_task_id is not null then select project_id into pid from public.tasks where id=p_task_id and deleted_at is null and public.project_access(project_id);if pid is null then raise exception 'Task unavailable';end if;end if;insert into public.focus_sessions(user_id,task_id,project_id,planned_seconds,resumed_at) values(auth.uid(),p_task_id,pid,p_minutes*60,now()) returning * into s;
 else if s.id is null then raise exception 'No active focus session';end if;delta=case when s.status='running' then greatest(0,extract(epoch from now()-s.resumed_at)::integer) else 0 end;
 if p_action='pause' and s.status='running' then update public.focus_sessions set elapsed_seconds=least(planned_seconds,elapsed_seconds+delta),resumed_at=null,status='paused' where id=s.id returning * into s;
 elsif p_action='resume' and s.status='paused' then update public.focus_sessions set resumed_at=now(),status='running' where id=s.id returning * into s;
 elsif p_action='extend' then update public.focus_sessions set planned_seconds=least(43200,planned_seconds+300) where id=s.id returning * into s;
 elsif p_action in ('end','complete') then if p_action='complete' and s.elapsed_seconds+delta<s.planned_seconds then raise exception 'Session has not finished';end if;update public.focus_sessions set elapsed_seconds=least(planned_seconds,elapsed_seconds+delta),status=case when p_action='complete' then 'completed' else 'ended' end,ended_at=now(),resumed_at=null where id=s.id returning * into s;else raise exception 'Invalid focus action';end if;end if;return s;end $$;
create function public.notify_message() returns trigger language plpgsql security definer set search_path='' as $$ begin insert into public.notifications(user_id,actor_id,kind,body) values(new.recipient_id,new.sender_id,'message','You have a new message');return new;end $$;
create trigger message_sent after insert on public.direct_messages for each row execute function public.notify_message();
create function public.sync_my_reminders() returns void language plpgsql security definer set search_path='' as $$ declare uid uuid:=auth.uid();prefs jsonb;today date:=(now() at time zone 'Asia/Tehran')::date;n integer;begin
 if uid is null then raise exception 'Sign in first';end if;select notifications into prefs from public.user_settings where user_id=uid;
 if coalesce((prefs->>'due_dates')::boolean,true) then insert into public.notifications(user_id,project_id,task_id,kind,body,dedupe_key) select uid,t.project_id,t.id,'due','Due today: '||t.title,'due:'||t.id||':'||today from public.tasks t where t.assignee_id=uid and t.due_date=today and t.status<>'Done' and t.deleted_at is null and public.project_access(t.project_id) on conflict(user_id,dedupe_key) do nothing;end if;
 if coalesce((prefs->>'meetings')::boolean,true) then insert into public.notifications(user_id,project_id,kind,body,dedupe_key) select uid,e.project_id,'meeting','Starting soon: '||e.title,'meeting:'||e.id||':'||e.starts_at from public.calendar_events e where (e.created_by=uid or uid=any(e.attendee_ids)) and e.starts_at>now() and e.starts_at<=now()+interval '5 minutes' and (e.project_id is null or public.project_access(e.project_id)) on conflict(user_id,dedupe_key) do nothing;end if;
 if coalesce((prefs->>'digest')::boolean,false) and extract(hour from now() at time zone 'Asia/Tehran')>=9 then select count(*) into n from public.tasks where assignee_id=uid and due_date<=today and status<>'Done' and deleted_at is null and public.project_access(project_id);insert into public.notifications(user_id,kind,body,dedupe_key) values(uid,'digest','Your day: '||n||' task(s) due today or overdue.','digest:'||today) on conflict(user_id,dedupe_key) do nothing;end if;end $$;
create function public.focus_finished_notice() returns trigger language plpgsql security definer set search_path='' as $$ begin if new.status='completed' and old.status<>'completed' and coalesce((select (notifications->>'focus_finished')::boolean from public.user_settings where user_id=new.user_id),true) then insert into public.notifications(user_id,project_id,task_id,kind,body,dedupe_key) values(new.user_id,new.project_id,new.task_id,'focus','Focus finished. Take a breather.','focus:'||new.id) on conflict(user_id,dedupe_key) do nothing;end if;return new;end $$;
create trigger focus_finished after update on public.focus_sessions for each row execute function public.focus_finished_notice();

revoke all on all tables in schema public from anon,authenticated;
grant select on public.profiles,public.projects,public.project_members,public.project_pins,public.tasks,public.task_status_events,public.subtasks,public.comments,public.milestones,public.calendar_events,public.focus_sessions,public.user_settings,public.notifications,public.activity_log,public.direct_messages to authenticated;
grant update(full_name,job_title,team,timezone,weekly_capacity,last_seen_at) on public.profiles to authenticated;
grant insert on public.projects,public.tasks,public.subtasks,public.comments,public.milestones,public.calendar_events,public.project_pins,public.direct_messages to authenticated;
grant update(name,description,status,color,icon,start_date,due_date,deleted_at) on public.projects to authenticated;
grant update(title,status,priority,assignee_id,due_date,estimate_hours,sort_order,deleted_at) on public.tasks to authenticated;
grant update(title,done) on public.subtasks to authenticated;
grant update(title,due_date,done) on public.milestones to authenticated;
grant update(title,type,starts_at,ends_at,location,meeting_url,attendee_ids) on public.calendar_events to authenticated;
grant update(theme,accent,wallpaper,glass,reduce_transparency,focus_minutes,break_minutes,notifications) on public.user_settings to authenticated;
grant update(read_at) on public.notifications,public.direct_messages to authenticated;
grant delete on public.subtasks,public.milestones,public.calendar_events,public.project_pins to authenticated;

alter table public.profiles enable row level security;
create policy profiles_read on public.profiles for select to authenticated using(public.shared_project(id));
create policy profiles_edit on public.profiles for update to authenticated using(id=auth.uid()) with check(id=auth.uid());
alter table public.projects enable row level security;
create policy projects_read on public.projects for select to authenticated using(owner_id=auth.uid() or public.project_access(id));
create policy projects_add on public.projects for insert to authenticated with check(owner_id=auth.uid() and deleted_at is null);
create policy projects_edit on public.projects for update to authenticated using(owner_id=auth.uid()) with check(owner_id=auth.uid());
alter table public.project_members enable row level security;
create policy members_read on public.project_members for select to authenticated using(user_id=auth.uid() or public.project_access(project_id));
alter table public.project_pins enable row level security;
create policy pins_read on public.project_pins for select to authenticated using(user_id=auth.uid());
create policy pins_add on public.project_pins for insert to authenticated with check(user_id=auth.uid() and public.project_access(project_id));
create policy pins_delete on public.project_pins for delete to authenticated using(user_id=auth.uid());
alter table public.tasks enable row level security;
create policy tasks_read on public.tasks for select to authenticated using(public.project_access(project_id));
create policy tasks_add on public.tasks for insert to authenticated with check(created_by=auth.uid() and public.project_access(project_id));
create policy tasks_edit on public.tasks for update to authenticated using(public.project_access(project_id)) with check(public.project_access(project_id));
alter table public.task_status_events enable row level security;
create policy task_history_read on public.task_status_events for select to authenticated using(public.project_access(project_id));
alter table public.subtasks enable row level security;
create policy subtasks_read on public.subtasks for select to authenticated using(public.task_access(task_id));
create policy subtasks_add on public.subtasks for insert to authenticated with check(public.task_access(task_id));
create policy subtasks_edit on public.subtasks for update to authenticated using(public.task_access(task_id)) with check(public.task_access(task_id));
create policy subtasks_delete on public.subtasks for delete to authenticated using(public.task_access(task_id));
alter table public.comments enable row level security;
create policy comments_read on public.comments for select to authenticated using(public.task_access(task_id));
create policy comments_add on public.comments for insert to authenticated with check(author_id=auth.uid() and public.task_access(task_id));
alter table public.milestones enable row level security;
create policy milestones_read on public.milestones for select to authenticated using(public.project_access(project_id));
create policy milestones_add on public.milestones for insert to authenticated with check(public.project_owner(project_id));
create policy milestones_edit on public.milestones for update to authenticated using(public.project_owner(project_id)) with check(public.project_owner(project_id));
create policy milestones_delete on public.milestones for delete to authenticated using(public.project_owner(project_id));
alter table public.calendar_events enable row level security;
create policy events_read on public.calendar_events for select to authenticated using((project_id is null and created_by=auth.uid()) or public.project_access(project_id));
create policy events_add on public.calendar_events for insert to authenticated with check(created_by=auth.uid() and (project_id is null or public.project_access(project_id)));
create policy events_edit on public.calendar_events for update to authenticated using((project_id is null and created_by=auth.uid()) or (public.project_access(project_id) and (created_by=auth.uid() or public.project_owner(project_id)))) with check((project_id is null and created_by=auth.uid()) or (public.project_access(project_id) and (created_by=auth.uid() or public.project_owner(project_id))));
create policy events_delete on public.calendar_events for delete to authenticated using((project_id is null and created_by=auth.uid()) or (public.project_access(project_id) and (created_by=auth.uid() or public.project_owner(project_id))));
alter table public.focus_sessions enable row level security;
create policy focus_read on public.focus_sessions for select to authenticated using(user_id=auth.uid() or public.project_access(project_id));
alter table public.user_settings enable row level security;
create policy settings_read on public.user_settings for select to authenticated using(user_id=auth.uid());
create policy settings_edit on public.user_settings for update to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
alter table public.notifications enable row level security;
create policy notifications_read on public.notifications for select to authenticated using(user_id=auth.uid());
create policy notifications_edit on public.notifications for update to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
alter table public.activity_log enable row level security;
create policy activity_read on public.activity_log for select to authenticated using(public.project_access(project_id));
alter table public.direct_messages enable row level security;
create policy messages_read on public.direct_messages for select to authenticated using(sender_id=auth.uid() or recipient_id=auth.uid());
create policy messages_add on public.direct_messages for insert to authenticated with check(sender_id=auth.uid() and public.shared_project(recipient_id) and read_at is null);
create policy messages_edit on public.direct_messages for update to authenticated using(recipient_id=auth.uid()) with check(recipient_id=auth.uid());
revoke execute on all functions in schema public from public,anon,authenticated;
grant execute on function public.project_access(uuid),public.project_owner(uuid),public.shared_project(uuid),public.task_access(uuid),public.find_registered_member(uuid,text),public.add_project_member(uuid,uuid,boolean),public.pending_invitations(),public.respond_invitation(uuid,boolean),public.remove_project_member(uuid,uuid),public.focus_command(text,uuid,integer),public.sync_my_reminders() to authenticated;
do $$ declare t text;begin if exists(select 1 from pg_publication where pubname='supabase_realtime') then foreach t in array array['projects','project_members','tasks','subtasks','comments','milestones','calendar_events','focus_sessions','notifications','direct_messages','activity_log'] loop if not exists(select 1 from pg_publication_tables where pubname='supabase_realtime' and schemaname='public' and tablename=t) then execute format('alter publication supabase_realtime add table public.%I',t);end if;end loop;end if;end $$;
commit;
